<?php

return array (
  'title' => 'Ինչպես փոխարկել Excel-ը PDF-ի առանց ֆորմատավորման խնդիրների (2026 ուղեցույց)',
  'description' => 'Իմացեք, թե ինչպես փոխարկել Excel-ը PDF-ի առանց ֆորմատավորման խնդիրների: Ուղղեք կտրված սյունակները, կոտրված դասավորությունները և դատարկ էջերը: Կարդացեք 2026 թվականի ուղեցույցը հիմա:',
  'main-heading' => 'Ինչպես փոխարկել Excel-ը PDF-ի առանց ֆորմատավորման խնդիրների (2026 ուղեցույց)',
  'intro-heading' => 'Ինչու է Excel-ը PDF-ի փոխարկումը սխալվում',
  'intro-para1' => 'Excel-ի աղյուսակը PDF-ի վերածելը պետք է լինի պարզ խնդիր, բայց այն մշտապես զարմացնում է մարդկանց: Սյունակները կտրվում են էջի աջ եզրին: Excel-ում լավ տեսք ունեցող տողերը թափվում են բազմաթիվ էջերի վրա անհարմար կետերում: Գծապատկերները հայտնվում են սխալ էջերում: Բջիջում կատարյալ տեղավորվող տեքստը կտրված է PDF ելքում: Գույների տեղաշարժ. Զգուշորեն կառուցված դասավորությունը, որի վրա աշխատել եք ժամերով, բոլորովին այլ փաստաթուղթ է թվում:',
  'intro-para2' => 'Այս խնդիրները պատահական չեն։ Նրանք բոլորն էլ բխում են նույն հիմնարար անհամապատասխանությունից. Excel-ը ցանցի վրա հիմնված ծրագիր է, որը չի մտածում էջերում, իսկ PDF-ը էջերի վրա հիմնված ձևաչափ է: Երբ դուք փոխարկում եք մեկից մյուսը, այդ անհամապատասխանությունը պետք է ինչ-որ կերպ լուծվի, և եթե դուք դա միտումնավոր չեք լուծում, Excel-ն անում է իր ընտրությունը, որը հաճախ ձեր ուզածը չէ:',
  'intro-para3' => 'Լավ նորությունն այն է, որ այս բոլոր խնդիրները կանխարգելելի են: Այս ուղեցույցը ներկայացնում է նախապատրաստման քայլերը, որոնք վերացնում են ձևաչափման խնդիրները մինչև փոխարկումը, և կոնկրետ կարգավորումները, որոնք վերահսկում են ելքը:',
  'step1-heading' => 'Քայլ 1. Սահմանեք ձեր տպման տարածքը',
  'step1-para1' => 'Տպման տարածքը Excel-ի ամենակարևոր և ամենաանտեսված կարգավորումներից մեկն է: Երբ տպման տարածքը սահմանված չէ, Excel-ը փորձում է ներառել բոլոր բջիջները, որոնք պարունակում են տվյալներ՝ PDF-ի փոխարկելու ժամանակ: Սա հաճախ ներառում է դատարկ բջիջներ, որոնք Excel-ը համարում է օգտագործված տիրույթի մաս, ինչը հանգեցնում է դատարկ էջերի կամ լրացուցիչ սյունակների, որոնք չպետք է հայտնվեն ելքում:',
  'step1-para2' => 'Տպման տարածքը կարգավորելու համար ընտրեք հենց այն բջիջները, որոնք ցանկանում եք հայտնվել PDF-ում: Այնուհետև ժապավենի մեջ գնացեք Էջի դասավորություն, կտտացրեք «Տպել տարածք» և ընտրեք «Սահմանել տպման տարածքը»: Ձեր ընտրության շուրջ կհայտնվի գծված եզրագիծ, որը հաստատում է, որ տարածքը սահմանված է:',
  'step1-para3' => 'Այս մեկ քայլը վերացնում է Excel-ի PDF ելքի անսպասելի դատարկ էջերի և լրացուցիչ բովանդակության ամենատարածված պատճառը:',
  'step2-heading' => 'Քայլ 2. Սահմանեք էջի կողմնորոշումը և չափը',
  'step2-para1' => 'Excel աղյուսակների մեծ մասն ավելի լայն է, քան բարձրությունը: Դիմանկարային կողմնորոշումը կտրում է սյուները աջ կողմում: Էջի դասավորություն ներդիրում Լանդշաֆտային կողմնորոշմանը անցնելը զգալիորեն ավելի մեծ հորիզոնական տարածք է տալիս և սովորաբար անմիջապես լուծում է կտրված սյունակների խնդիրը:',
  'step2-para2' => 'Սահմանեք թղթի չափը, որպեսզի համապատասխանի այն, ինչի վրա տպելու են ձեր ստացողները: Շատ երկրների համար A4-ը ստանդարտ է: ԱՄՆ ստացողների համար նամակի չափը նորմ է: Թղթի սխալ չափի օգտագործումը չի ազդում PDF-ի էկրանին տեսքի վրա, սակայն այն ձևաչափման հետ կապված խնդիրներ է առաջացնում, երբ ստացողը փորձում է տպել:',
  'step3-heading' => 'Քայլ 3. Օգտագործեք Scale to Fit',
  'step3-para1' => '«Էջի դասավորություն» ներդիրի «Scale to Fit» ընտրանքները հատուկ նախագծված են էջից լցված բովանդակության խնդիրը լուծելու համար: Ամենաօգտակար տարբերակն է Fit All Columns on One Page, որը կրճատում է ձեր աղյուսակի հորիզոնական մասշտաբը, մինչև բոլոր սյունակները տեղավորվեն էջի լայնության մեջ: Տողերը բնականաբար շարունակում են ճեղքվել էջերում, բայց ոչ մի սյունակ չի կտրվում:',
  'step3-para2' => 'Եթե ​​ձեր աղյուսակն ունի բազմաթիվ տողեր, ինչպես նաև բազմաթիվ սյունակներ, մտածեք երկու չափսերն էլ սահմանելու մասին. Fit Sheet-ը մեկ էջի վրա ստիպում է ամեն ինչ մեկ էջի վրա՝ փոքրացնելով այնքան, որքան անհրաժեշտ է: Իմացեք, որ եթե ձեր աղյուսակը մեծ է, դա կարող է տեքստը շատ փոքր դարձնել: Միշտ ստուգեք արդյունքը տպագրության նախադիտման մեջ, նախքան վերջնական տեսքը:',
  'step4-heading' => 'Քայլ 4. Կրկնել վերնագրի տողերը յուրաքանչյուր էջում',
  'step4-para1' => 'Այն աղյուսակների համար, որոնք ընդգրկում են մի քանի էջ, սյունակների վերնագրերի առկայությունը միայն առաջին էջում դժվարացնում է հետագա էջերը կարդալը: Excel-ը կարող է ավտոմատ կերպով կրկնել ձեր վերնագրի տողը PDF ելքի յուրաքանչյուր էջի վերևում:',
  'step4-para2' => 'Գնացեք Էջի դասավորություն և սեղմեք Տպել վերնագրերը: Վերևում կրկնվող տողերում մուտքագրեք ձեր վերնագրի տողի հղումը: Օրինակ, մուտքագրեք դոլարի նշան 1 կրկնակետ դոլարի նշան 1՝ յուրաքանչյուր էջի 1-ին տողը կրկնելու համար: Սա փոքր պարամետր է, որը զգալի տարբերություն է դնում բազմաէջանոց աղյուսակների PDF-ների ընթեռնելիության հարցում:',
  'step5-heading' => 'Քայլ 5. Ստուգեք տպման նախադիտումը մինչ արտահանումը',
  'step5-para1' => 'Այս քայլը բաց է թողնվում ավելի հաճախ, քան ցանկացած այլ քայլ և հաշվի է առնում կանխարգելվող ձևաչափման անակնկալների մեծ մասը: Նախքան PDF արտահանելը, անցեք Ֆայլ, ապա Տպել: Սա բացում է տպման նախադիտումը, որը ցույց է տալիս, թե ինչ տեսք կունենա PDF ելքը՝ էջ առ էջ:',
  'step5-para2' => 'Ոլորեք յուրաքանչյուր էջ և ստուգեք՝ տեսանելի՞ են արդյոք բոլոր սյունակները: Վերնագրերը կրկնվու՞մ են: Արդյո՞ք գծապատկերները ճիշտ էջերում են: Արդյո՞ք որևէ բովանդակություն կրճատված է: Կա՞ն անսպասելի դատարկ էջեր: Print Preview-ում խնդիրների շտկումը տևում է մի քանի վայրկյան: Հաճախորդի հետ PDF-ը համօգտագործելուց հետո դրանք շտկելը շատ ավելի երկար է տևում:',
  'step6-heading' => 'Քայլ 6. Արտահանել՝ օգտագործելով Excel-ի բնիկ արտահանման գործառույթը',
  'step6-para1' => 'Ամբողջ գործընթացում ամենակարևոր ընտրությունն այն է, թե ինչպես եք ստեղծում PDF-ը: Excel-ի հայրենի արտահանման գործառույթը տալիս է ամենաբարձր որակը և ճշգրիտ արդյունքը, քանի որ այն օգտագործում է Excel-ի սեփական արտահանման շարժիչը, որը ճշգրիտ հասկանում է Excel-ի էջի դասավորության բոլոր կարգավորումները:',
  'step6-para2' => 'Գնացեք Ֆայլ, այնուհետև Արտահանեք, ապա Ստեղծեք PDF/XPS: Բացվող երկխոսության մեջ ընտրեք «Ստանդարտ որակ» տպագրվող փաստաթղթերի համար կամ «Նվազագույն չափս»՝ միայն էկրանին ընթերցվող փաստաթղթերի համար: Սեղմեք Հրապարակել՝ ֆայլը ստեղծելու համար:',
  'step6-para3' => 'Խուսափեք Տպել PDF մեթոդից (վիրտուալ PDF տպիչ օգտագործելով) Excel ֆայլերի համար: Այս մոտեցումը աղյուսակը վերածում է օպերացիոն համակարգի տպման վարորդի, այլ ոչ թե Excel-ի սեփական շարժիչի միջոցով, որն անտեսում է դասավորության որոշ կարգավորումներ և ավելի ցածր որակի արդյունքներ է տալիս:',
  'online-converter-heading' => 'Երբ օգտագործել առցանց փոխարկիչը',
  'online-converter-para' => 'Առցանց փոխարկիչները, ինչպիսիք են PDFTools-ը, առավել օգտակար են, երբ անհրաժեշտ է Excel ֆայլ փոխարկել մի սարքի վրա, որտեղ տեղադրված չէ Microsoft Excel: Word to PDF գործիքը PDFTools-ում ընդունում է Excel ֆայլերը, ինչպես նաև Word փաստաթղթերը և հուսալիորեն մշակում է պարզ աղյուսակներ: Պայմանական ձևաչափմամբ, առանցքային աղյուսակներով կամ դասավորության բարդ կանոններով բարդ աղյուսակների համար Excel-ի արտահանումը միշտ ավելի ճշգրիտ տարբերակ է:',
  'common-problems-heading' => 'Ընդհանուր խնդիրների շտկում',
  'problem1-heading' => 'Կողմնորոշումը փոխելուց հետո սյունակները դեռ կտրված են',
  'problem1-text' => 'Եթե ​​լանդշաֆտային կողմնորոշումը բավարար չէ, կրճատեք առանձին սյունակների լայնությունը, մի փոքր ավելացրեք լուսանցքները կամ օգտագործեք ավելի փոքր տառաչափ աղյուսակի համար: Կարող եք նաև հաշվի առնել, թե արդյոք որոշ սյունակներ կարող են թաքցվել PDF արտահանման համար՝ առանց էական տեղեկությունները կորցնելու:',
  'problem2-heading' => 'Գծապատկերները հայտնվում են սխալ էջում',
  'problem2-text' => 'Տեղադրեք ձեռքով էջի ընդմիջումները գծապատկերից առաջ և հետո՝ անցնելով Էջի դասավորություն և սեղմելով Տեղադրել էջի ընդմիջում: Որպես այլընտրանք, գծապատկերները տեղափոխեք հատուկ գծապատկերների թերթեր՝ աջ սեղմելով գծապատկերի վրա և ընտրելով Տեղափոխել գծապատկերը, այնուհետև ընտրելով Նոր թերթ:',
  'problem3-heading' => 'Վերջում հայտնվում են դատարկ էջեր',
  'problem3-text' => 'Վերջում դատարկ էջերը գրեթե միշտ պայմանավորված են տպման տարածքով, ներառյալ ձեր տվյալների տակ գտնվող դատարկ բջիջները, կամ ձեռքով չհեռացված էջի ընդմիջումից: Մաքրել էջի բոլոր ընդմիջումները՝ անցնելով Էջի դասավորություն, սեղմելով «Ընդմիջումներ» և ընտրելով «Վերականգնել բոլոր էջի ընդմիջումները»: Այնուհետև վերասահմանեք ձեր տպման տարածքը:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'Excel-ի PDF-ի փոխակերպման ֆորմատավորման խնդիրները գրեթե միշտ պայմանավորված են այնպիսի կարգավորումներով, որոնք երբեք չեն կազմաձևվել, այլ ոչ թե փոխակերպման գործիքի կողմից: Տպման տարածքի կարգավորումը, ճիշտ կողմնորոշումը ընտրելը, Scale to Fit-ի օգտագործումը, վերնագրի տողերի կրկնումը և տպման նախադիտումը ստուգելը մինչև արտահանումը կվերացնի խնդիրների ճնշող մեծամասնությունը՝ նախքան դրանք առաջանալը:',
  'conclusion-para2' => 'Արտահանման քայլի համար միշտ օգտագործեք Excel-ի բնիկ Ստեղծել PDF/XPS ֆունկցիան, քան վիրտուալ տպագրությունը: Եթե ​​Ձեզ անհրաժեշտ է նվազեցնել ստացված ֆայլի չափը էլեկտրոնային փոստով ուղարկելու համար, PDFTools-ի կոմպրեսիոն գործիքը արագ լուծում է այն արտահանումից հետո: Բազմաթիվ աղյուսակների PDF ֆայլերը մեկ փաստաթղթի մեջ միավորելու համար PDFTools-ում անվճար հասանելի է միաձուլման PDF գործիքը:',
  'faqs-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-question' => 'Ինչու է Excel PDF-ը տարբերվում տարբեր համակարգիչների վրա:',
  'faq1-answer' => 'Excel-ն օգտագործում է համակարգային տառատեսակներ էկրանին ցուցադրելիս, սակայն տառատեսակի տվյալները տեղադրում է PDF արտահանման մեջ: Եթե ​​PDF-ը ստեղծվել է Excel-ի հայրենի արտահանմամբ, այն պետք է նույնական տեսք ունենա յուրաքանչյուր սարքի վրա: Եթե ​​այն ստեղծվել է PDF-ով տպագրելու միջոցով, տառատեսակի ցուցադրումը կարող է փոքր-ինչ տարբերվել:',
  'faq2-question' => 'Կարո՞ղ եմ Excel-ի մի քանի թերթիկ փոխակերպել մեկ PDF-ի:',
  'faq2-answer' => 'Այո՛։ Աջ սեղմեք թերթի ցանկացած ներդիր և ընտրեք «Ընտրել բոլոր թերթերը», կամ «Ctrl» սեղմեք առանձին ներդիրների վրա՝ կոնկրետները ընտրելու համար: Այնուհետև օգտագործեք Ֆայլը, այնուհետև արտահանեք, ապա ստեղծեք PDF/XPS: Excel-ը ներառում է բոլոր ընտրված թերթերը որպես հաջորդական էջեր մեկ PDF ֆայլում:',
  'faq3-question' => 'Արդյո՞ք PDF-ը պահում է Excel բանաձևերը:',
  'faq3-answer' => 'Ոչ: PDF-ը ներկայացման ձևաչափ է, այլ ոչ թե հաշվարկման ձևաչափ: PDF-ը ցույց է տալիս բանաձևեր պարունակող բջիջների ընթացիկ արժեքները, բայց բանաձևերն իրենք ներառված չեն: Ստացողները չեն կարող փոփոխել արժեքները կամ վերահաշվարկել: Եթե ​​ստացողները պետք է աշխատեն կենդանի տվյալների հետ, փոխարենը ուղարկեք Excel ֆայլը:',
  'faq4-question' => 'Ինչպե՞ս կարող եմ համոզվել, որ գծապատկերները PDF-ում հստակ տեսք ունեն:',
  'faq4-answer' => 'Excel-ում բնօրինակ ստեղծված գծապատկերները PDF արտահանման մեջ վերածվում են վեկտորային գրաֆիկայի, ինչը նշանակում է, որ դրանք մնում են կտրուկ խոշորացման ցանկացած մակարդակում: Գծապատկերները, որոնք տեղադրվել են որպես պատկերներ, այլ ոչ թե ստեղծվել են Excel-ում, կարող են ավելի մեղմ թվալ: Օգտագործեք բնիկ Excel գծապատկերներ, որտեղ հնարավոր է ամենասուր արդյունքը:',
  'a' => 'Բառից PDF',
  'online-converter-para-1' => 'Word to PDF գործիք PDFTools-ում ընդունում է Excel ֆայլերը, ինչպես նաև Word փաստաթղթերը և հուսալիորեն մշակում է պարզ աղյուսակներ: Պայմանական ձևաչափմամբ, առանցքային աղյուսակներով կամ դասավորության բարդ կանոններով բարդ աղյուսակների համար Excel-ի արտահանումը միշտ ավելի ճշգրիտ տարբերակ է:',
  'a2' => 'սեղմել PDF-ը',
  'conclusion-para3' => 'PDFTools-ի գործիքը դա արագ է լուծում արտահանումից հետո: Բազմաթիվ աղյուսակների PDF ֆայլերը մեկ փաստաթղթի մեջ միավորելու համար՝',
  'a3' => 'միաձուլել PDF-ը',
  'conclusion-para4' => 'գործիքը հասանելի է անվճար PDFTools-ում:',
);
